import { tracked } from "@glimmer/tracking";
import { ajax } from "discourse/lib/ajax";

export default class ProcessList {
  @tracked output = null;

  async refresh() {
    const result = await ajax("/admin/docker/ps", {
      dataType: "text",
    });

    this.output = result;
  }
}

import { cached, tracked } from "@glimmer/tracking";
import { capitalize } from "@ember/string";
import { TrackedObject } from "@ember-compat/tracked-built-ins";
import AdminPlugin from "discourse/admin/models/admin-plugin";
import { ajax } from "discourse/lib/ajax";

let loaded = [];
export let needsImageUpgrade = false;

function concatVersions(repos) {
  return repos.map((repo) => repo.version).join(", ");
}

export default class Repo {
  static create() {
    return new Repo(...arguments);
  }

  static async findAll() {
    if (loaded.length) {
      return loaded;
    }

    const result = await ajax("/admin/docker/repos");
    loaded = result.repos.map((r) => new Repo(r));
    needsImageUpgrade = result.upgrade_required;

    return loaded;
  }

  static async findUpgrading() {
    const result = await Repo.findAll();
    return result.find((item) => item.upgrading === true);
  }

  static async find(id) {
    const result = await Repo.findAll();
    return result.find((item) => item.id === id);
  }

  static upgradeAll() {
    return ajax("/admin/docker/update", {
      dataType: "text",
      type: "POST",
      data: { path: "all" },
    });
  }

  static resetAll(repos) {
    return ajax("/admin/docker/update", {
      dataType: "text",
      type: "DELETE",
      data: { path: "all", version: concatVersions(repos) },
    });
  }

  static async findLatestAll() {
    const result = await ajax("/admin/docker/latest", {
      dataType: "json",
      type: "GET",
      data: { path: "all" },
    });
    return result.repos;
  }

  static async findAllProgress(repos) {
    const result = await ajax("/admin/docker/progress", {
      dataType: "json",
      type: "GET",
      data: { path: "all", version: concatVersions(repos) },
    });
    return result.progress;
  }

  @tracked unloaded = true;
  @tracked checking = false;
  @tracked lastCheckedAt = null;
  @tracked latest = new TrackedObject({});
  @tracked plugin = null;

  // model attributes
  @tracked name = null;
  @tracked path = null;
  @tracked branch = null;
  @tracked official = false;
  @tracked fork = false;
  @tracked id = null;
  @tracked version = null;
  @tracked pretty_version = null;
  @tracked url = null;
  @tracked upgrading = false;

  constructor(attributes = {}) {
    if (attributes.latest) {
      for (const [key, value] of Object.entries(attributes.latest)) {
        this.latest[key] = value;
      }
    }

    if (attributes.plugin) {
      this.plugin = AdminPlugin.create(attributes.plugin);
    }

    for (const [key, value] of Object.entries(attributes)) {
      if (["latest", "plugin"].includes(key)) {
        continue;
      }

      this[key] = value;
    }
  }

  @cached
  get nameTitleized() {
    if (this.plugin) {
      return this.plugin.nameTitleized;
    }

    return capitalize(this.name);
  }

  get linkUrl() {
    if (this.plugin) {
      return this.plugin.linkUrl;
    }

    return this.url;
  }

  get author() {
    if (this.plugin) {
      return this.plugin.author;
    }

    return null;
  }

  get checkingStatus() {
    return this.unloaded || this.checking;
  }

  get upToDate() {
    return !this.upgrading && this.version === this.latest?.version;
  }

  get hasNewVersion() {
    return !this.checkingStatus && !this.upToDate;
  }

  get prettyVersion() {
    return this.pretty_version || this.version?.substring(0, 8);
  }

  get prettyLatestVersion() {
    return this.latest?.pretty_version || this.latest?.version?.substring(0, 8);
  }

  get shouldCheck() {
    if (this.version === null) {
      return false;
    }

    if (this.checking) {
      return false;
    }

    // Only check once every minute
    if (this.lastCheckedAt) {
      const ago = new Date().getTime() - this.lastCheckedAt;
      return ago > 60 * 1000;
    }

    return true;
  }

  repoAjax(url, args = {}) {
    args.data = {
      path: this.path,
      version: this.version,
      branch: this.branch,
    };

    return ajax(url, args);
  }

  async findLatest() {
    if (!this.shouldCheck) {
      this.unloaded = false;
      return;
    }

    this.checking = true;

    const result = await this.repoAjax("/admin/docker/latest");

    this.unloaded = false;
    this.checking = false;
    this.lastCheckedAt = new Date().getTime();

    for (const [key, value] of Object.entries(result.latest)) {
      this.latest[key] = value;
    }
  }

  async findProgress() {
    const result = await this.repoAjax("/admin/docker/progress");
    return result.progress;
  }

  async resetUpgrade() {
    await this.repoAjax("/admin/docker/update", {
      dataType: "text",
      type: "DELETE",
    });

    this.upgrading = false;
  }

  async startUpgrade() {
    this.upgrading = true;

    try {
      await this.repoAjax("/admin/docker/update", {
        dataType: "text",
        type: "POST",
      });
    } catch {
      this.upgrading = false;
    }
  }
}

import { click, currentURL, visit } from "@ember/test-helpers";
import { test } from "qunit";
import pretender, { response } from "discourse/tests/helpers/create-pretender";
import { acceptance } from "discourse/tests/helpers/qunit-helpers";

acceptance("docker_manager", function (needs) {
  needs.user({ admin: true });

  test("basic navigation", async function (assert) {
    await visit("/admin");
    assert.dom(".upgrades-banner").exists();

    pretender.get("/admin/docker/repos", () =>
      response({
        repos: [
          {
            name: "discourse",
            path: "/home/user/discourse/discourse",
            branch: "origin/main",
            official: false,
            id: "discourse",
            version: "010370f8b1cfa56cea3736059c96d0578e7918e2",
            pretty_version: "v3.1.0.beta2 +236",
            url: "https://github.com/discourse/discourse.git",
          },
          {
            name: "docker_manager",
            path: "/home/user/discourse/discourse/plugins/docker_manager",
            branch: "origin/v2",
            official: true,
            id: "docker_manager",
            version: "c8bca160d5c04a569217ede084bbf844ecd21644",
            pretty_version: null,
            url: "https://github.com/discourse/docker_manager",
          },
        ],
      })
    );

    pretender.get("/admin/docker/latest", ({ queryParams }) => {
      if (queryParams.path === "/home/user/discourse/discourse") {
        return response({
          latest: {
            path: "/home/user/discourse/discourse",
            version: "8efb787d8758cbe2ddc6a42b79cbdfa0e0b1909a",
            pretty_version: "v3.1.0.beta2 +241",
            commits_behind: 0,
            date: "2023-02-13T10:43:16.000+01:00",
          },
        });
      } else {
        return response({
          latest: {
            path: "/home/user/discourse/discourse/plugins/docker_manager",
            version: "c8bca160d5c04a569217ede084bbf844ecd21644",
            pretty_version: null,
            commits_behind: 0,
            date: "2023-02-13T11:25:49.000+01:00",
          },
        });
      }
    });

    await click(".upgrades-banner a");
    assert.strictEqual(currentURL(), "/admin/update");

    assert.dom(".docker-manager table#repos tbody tr").exists({ count: 2 });
    assert.dom(".new.commit-hash").hasText("v3.1.0.beta2 +241");

    pretender.get("/admin/docker/progress", () =>
      response({
        progress: {
          logs: "",
          percentage: 0,
          status: null,
          repos: ["discourse"],
        },
      })
    );

    await click(".upgrade-button");

    assert.dom("h2").hasText("Update discourse");
    assert.dom("button.start-upgrade").exists();
  });
});

import { getOwner } from "@ember/owner";
import { render, settled } from "@ember/test-helpers";
import { setupRenderingTest } from "ember-qunit";
import { module, test } from "qunit";
import RepoStatus from "discourse/plugins/docker_manager/discourse/components/repo-status";

const repoProps = {
  unloaded: false,
  branch: "origin/main",
  id: "discourse",
  name: "discourse",
  official: false,
  path: "/c/discourse",
  pretty_version: "v2.2.0.beta6 +98",
  url: "https://github.com/discourse/discourse",
  version: "8f65e4f",
  latest: {
    commits_behind: 3,
    date: "2018-12-26T20:52:07.000+03:00",
    path: "/c/discourse",
    pretty_version: "v2.2.0.beta6 +101",
    version: "2b006c0",
  },
};

const managerProps = {
  unloaded: false,
  branch: "origin/main",
  id: "docker_manager",
  name: "docker_manager",
  official: true,
  path: "/c/discourse/plugins/docker_manager",
  pretty_version: null,
  url: "https://github.com/discourse/docker_manager",
  version: "0b1fb4b",
  latest: {
    commits_behind: 0,
    date: "2018-12-26T20:52:07.000+03:00",
    path: "/c/discourse/plugins/docker_manager",
    pretty_version: null,
    version: "0b1fb4b",
  },
};

module("Integration | Component | RepoStatus", function (hooks) {
  setupRenderingTest(hooks);

  test("renders correctly", async function (assert) {
    const store = getOwner(this).lookup("service:store");
    this.set("repo", store.createRecord("repo", repoProps));
    this.set("managerRepo", store.createRecord("repo", managerProps));

    await render(
      <template>
        <RepoStatus @repo={{this.repo}} @managerRepo={{this.managerRepo}} />
      </template>
    );

    assert
      .dom("a.current.commit-hash")
      .hasText("v2.2.0.beta6 +98", "tag version is used when present");
    assert
      .dom("a.new.commit-hash")
      .hasText("v2.2.0.beta6 +101", "tag version is used when present");

    assert
      .dom("div.new-commits a")
      .hasText("3 new commits", "shows number of new commits");
    assert
      .dom("div.new-commits a")
      .hasAttribute(
        "href",
        "https://github.com/discourse/discourse/compare/8f65e4f...2b006c0",
        "links to GitHub diff page"
      );

    this.repo.pretty_version = null;
    this.repo.latest.pretty_version = null;
    await settled();

    assert
      .dom("a.current.commit-hash")
      .hasText("8f65e4f", "commit hash is used when tag version is absent");
    assert
      .dom("a.new.commit-hash")
      .hasText("2b006c0", "commit hash is used when tag version is absent");
  });

  test("official plugin", async function (assert) {
    const store = getOwner(this).lookup("service:store");
    this.set(
      "repo",
      store.createRecord("repo", {
        ...repoProps,
        plugin: { name: "discourse", isOfficial: true },
      })
    );
    this.set("managerRepo", store.createRecord("repo", managerProps));

    await render(
      <template>
        <RepoStatus @repo={{this.repo}} @managerRepo={{this.managerRepo}} />
      </template>
    );

    assert
      .dom("div.d-table__overview-author")
      .hasText("By Discourse", "shows plugin author");
  });

  test("update button", async function (assert) {
    const store = getOwner(this).lookup("service:store");
    this.set("repo", store.createRecord("repo", repoProps));
    this.set("managerRepo", store.createRecord("repo", managerProps));

    await render(
      <template>
        <RepoStatus @repo={{this.repo}} @managerRepo={{this.managerRepo}} />
      </template>
    );

    assert
      .dom(".upgrade-button")
      .exists("update button is visible when plugin is out-of-date")
      .isNotDisabled(
        "update button is not disabled when docker_manager repo is out-of-date"
      );

    this.managerRepo.version = "022aa3a";
    await settled();

    assert
      .dom(".upgrade-button")
      .isDisabled(
        "update button is disabled when docker_manager repo is not up-to-date"
      );

    this.repo.latest.commits_behind = 0;
    this.repo.version = "2b006c0";
    this.repo.pretty_version = "v2.2.0.beta6 +101";
    await settled();

    assert
      .dom(".upgrade-button")
      .doesNotExist("update button is not visible when plugin is up-to-date");
  });
});

